    expect(result).toEqual({valid: true, data: {type: 'user_message', content: 'hello'}});
  });

  it('accepts list_sessions with optional limit and before while stripping extra fields and rejecting malformed values', () => {
    const bare = validateMessage({type: 'list_sessions'});
    const full = validateMessage({
      type: 'list_sessions',
      limit: 0,
      before: {updatedAt: 1767225600000, sessionId: 's1', extra: 'drop'},
      userId: 'u2',
    });
    const iso = validateMessage({
      type: 'list_sessions',
      limit: 25,
      before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(128)},
    });
    const invalidPayloads = [
      {type: 'list_sessions', limit: 'ten'},
      {type: 'list_sessions', limit: -1},
      {type: 'list_sessions', limit: 1.5},
      {type: 'list_sessions', before: 'not-an-object'},
      {type: 'list_sessions', before: []},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: ''}},
      {type: 'list_sessions', before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(129)}},
      {type: 'list_sessions', before: {updatedAt: 'not-a-date', sessionId: 's1'}},
      {type: 'list_sessions', before: {updatedAt: Number.POSITIVE_INFINITY, sessionId: 's1'}},
      {type: 'list_sessions', before: {updatedAt: true, sessionId: 's1'}},
    ];

    expect({
      bare,
      full,
      iso,
      rejected: invalidPayloads.map(payload => validateMessage(payload).valid),
    }).toEqual({
      bare: {valid: true, data: {type: 'list_sessions'}},
      full: {
        valid: true,
        data: {type: 'list_sessions', limit: 0, before: {updatedAt: 1767225600000, sessionId: 's1'}},
      },
      iso: {
        valid: true,
        data: {
          type: 'list_sessions',
          limit: 25,
          before: {updatedAt: '2026-01-01T00:00:00.000Z', sessionId: 'a'.repeat(128)},
        },
      },
      rejected: Array(invalidPayloads.length).fill(false),
    });
  });
});

